CAT = "deeinbWahlen"; SEG = "WAH"
# Wahlen, Parteien und Mitwirkung (Modul II Teil 1 Wahlen und Parteien; Teil 2 Verantwortung
# für das Gemeinwohl; Teil 3 Konflikte in der Politik). GG Art. 21, 38; BWahlG §§ 1, 2; EuWG § 6.
Q = [
('Eine 17-Jährige möchte bei der Bundestagswahl abstimmen. Was gilt?',
 'Sie darf erst mit 18 wählen', ['Sie darf mit Zustimmung der Eltern wählen', 'Sie darf nur die Erststimme abgeben', 'Sie darf nur per Briefwahl wählen'],
 'Artikel 38 Absatz 2: Wahlberechtigt ist, wer das achtzehnte Lebensjahr vollendet hat. Bei Europawahlen liegt die Grenze inzwischen niedriger.'),
('Ab welchem Alter dürfen Deutsche bei der Europawahl wählen?',
 '16 Jahre', ['18 Jahre', '17 Jahre', '21 Jahre'],
 'Nach § 6 des Europawahlgesetzes ist wahlberechtigt, wer am Wahltag das sechzehnte Lebensjahr vollendet hat.'),
('Welcher Wahlgrundsatz verlangt, dass niemand sehen darf, wie jemand abstimmt?',
 'Geheime Wahl', ['Allgemeine Wahl', 'Gleiche Wahl', 'Unmittelbare Wahl'],
 'Die geheime Wahl schützt vor Druck: Deshalb füllt man den Stimmzettel allein in der Kabine aus.'),
('Was bedeutet der Grundsatz der gleichen Wahl?',
 'Jede Stimme zählt gleich viel', ['Alle müssen dieselbe Partei wählen', 'Männer und Frauen wählen getrennt', 'Jede Partei bekommt gleich viele Sitze'],
 'Gleiche Wahl heißt: Jede Stimme hat das gleiche Gewicht, egal wer sie abgibt.'),
('Ein Arbeitgeber verlangt, dass seine Angestellten eine bestimmte Partei wählen. Welcher Grundsatz wird verletzt?',
 'Freie Wahl', ['Gleiche Wahl', 'Allgemeine Wahl', 'Unmittelbare Wahl'],
 'Die freie Wahl verbietet jeden Zwang oder Druck auf die Wählerinnen und Wähler. Wen man wählt, entscheidet man selbst.'),
('Wofür gibt man bei der Bundestagswahl die Erststimme ab?',
 'Für eine Person im eigenen Wahlkreis', ['Für die Kanzlerkandidatur', 'Für eine Landesliste', 'Für das Staatsoberhaupt'],
 'Mit der Erststimme wählt man eine Bewerberin oder einen Bewerber im Wahlkreis. Seit der Reform von 2023 bekommt der Sieger den Sitz nur, wenn die Zweitstimmen seiner Partei ihn decken.'),
('Welche Stimme entscheidet bei der Bundestagswahl vor allem über die Sitzverteilung?',
 'Die Zweitstimme', ['Die Erststimme', 'Die Mitgliederzahl', 'Die letzte Umfrage'],
 'Nach § 1 Bundeswahlgesetz gelten die Grundsätze der Verhältniswahl. Die Sitze werden nach den Zweitstimmen auf die Parteien verteilt.'),
('Wie viele Abgeordnete hat der Bundestag nach dem Bundeswahlgesetz?',
 '630', ['598', '709', '736'],
 '§ 1 Bundeswahlgesetz legt seit der Wahlrechtsreform 630 Abgeordnete fest. Früher wuchs der Bundestag durch Überhang- und Ausgleichsmandate auf über 700.'),
('Eine Partei erhält 4 Prozent der Zweitstimmen, gewinnt aber drei Wahlkreise. Was gilt nach dem geltenden Wahlrecht?',
 'Sie bekommt Sitze nach ihrem Zweitstimmenanteil', ['Sie bekommt nur die drei Wahlkreissitze', 'Sie bekommt keinen einzigen Sitz', 'Sie muss zuerst eine Koalition eingehen'],
 'Normalerweise braucht eine Partei 5 Prozent der Zweitstimmen. Nach dem Urteil des Bundesverfassungsgerichts von 2024 nimmt eine Partei bis zu einer Neuregelung aber auch an der Sitzverteilung teil, wenn sie in mindestens drei Wahlkreisen die meisten Erststimmen hat.'),
('Sie sind am Wahltag verreist. Wie können Sie trotzdem an der Bundestagswahl teilnehmen?',
 'Per Briefwahl', ['Per E-Mail an das Wahlamt', 'Durch einen Anruf im Rathaus', 'Ein Nachbar stimmt für Sie ab'],
 'Die Briefwahl beantragt man bei der Gemeinde. Jemand anderen für sich wählen zu lassen, ist nicht erlaubt.'),
('Sie haben Ihre Wahlbenachrichtigung verloren, stehen aber im Wählerverzeichnis. Können Sie trotzdem wählen?',
 'Ja, mit Personalausweis oder Reisepass', ['Nein, nur mit der Benachrichtigung', 'Nur per Briefwahl', 'Nur mit einem Zeugen aus der Nachbarschaft'],
 'Entscheidend ist der Eintrag im Wählerverzeichnis. Wer seine Benachrichtigung nicht dabeihat, weist sich im Wahllokal mit einem amtlichen Ausweis aus.'),
('Was ist nach dem Grundgesetz eine Aufgabe der Parteien?',
 'Bei der politischen Willensbildung mitwirken', ['Gesetze allein beschließen', 'Gerichte kontrollieren', 'Steuern einziehen'],
 'Artikel 21 Absatz 1: Die Parteien wirken bei der politischen Willensbildung des Volkes mit. Gesetze beschließt das Parlament.'),
('Was verlangt das Grundgesetz von der inneren Ordnung einer Partei?',
 'Sie muss demokratisch sein', ['Sie muss vom Staat geführt werden', 'Sie muss eine Religion haben', 'Sie muss geheim bleiben'],
 'Artikel 21 Absatz 1: Die innere Ordnung der Parteien muss demokratischen Grundsätzen entsprechen.'),
('Worüber müssen Parteien öffentlich Rechenschaft geben?',
 'Herkunft und Verwendung ihrer Mittel', ['Die Namen aller Wähler', 'Die Namen und Wohnorte ihrer Mitglieder', 'Ihre internen Umfragen'],
 'Artikel 21 Absatz 1: Die Parteien müssen über Herkunft und Verwendung ihrer Mittel und über ihr Vermögen öffentlich Rechenschaft geben.'),
('Was halten Parteien, die gemeinsam regieren wollen, in einem Koalitionsvertrag fest?',
 'Ihre gemeinsamen politischen Ziele', ['Das Ergebnis der nächsten Wahl', 'Die Namen ihrer Mitglieder', 'Die Urteile des Verfassungsgerichts'],
 'Vor der Kanzlerwahl einigen sich die Koalitionsparteien auf ein Programm für die Wahlperiode und auf die Verteilung der Ministerien. Rechtlich bindend ist der Vertrag nicht.'),
('Wie viele Abgeordnete braucht eine Fraktion im Bundestag nach der Geschäftsordnung mindestens?',
 'Fünf Prozent der Mitglieder des Bundestags', ['Zehn Abgeordnete', 'Ein Drittel der Mitglieder des Bundestags', 'Einen Abgeordneten aus jedem Land'],
 '§ 10 der Geschäftsordnung des Bundestags: Eine Fraktion braucht mindestens fünf Prozent der Mitglieder. Abgeordnete einer Partei, die darunter liegen, können eine Gruppe bilden.'),
('Darf man im Wahllokal zusehen, wenn die Stimmen ausgezählt werden?',
 'Ja, die Auszählung ist öffentlich', ['Nein, nur der Wahlvorstand ist dabei', 'Nur Mitglieder der Parteien', 'Nur mit Genehmigung der Polizei'],
 'Nach § 31 Bundeswahlgesetz sind Wahlhandlung und Ermittlung des Ergebnisses öffentlich. Jeder darf zuschauen, solange er die Arbeit der ehrenamtlichen Wahlhelfer nicht stört.'),
('Wie viele Schöffen entscheiden im Schöffengericht am Amtsgericht neben dem Berufsrichter mit?',
 'Zwei', ['Einer', 'Sechs', 'Zwölf'],
 '§ 29 Gerichtsverfassungsgesetz: Das Schöffengericht besteht aus dem Richter beim Amtsgericht und zwei Schöffen. Die ehrenamtlichen Richter haben das gleiche Stimmrecht wie der Berufsrichter.'),
('Anwohner gründen eine Gruppe gegen eine geplante Umgehungsstraße. Wie nennt man das?',
 'Bürgerinitiative', ['Gewerkschaft', 'Genossenschaft', 'Bürgerversammlung'],
 'In einer Bürgerinitiative setzen sich Menschen gemeinsam für ein konkretes Anliegen ein, oft in ihrer Gemeinde.'),
('Was gilt meist für eine Demonstration unter freiem Himmel?',
 'Sie wird vorher bei der Behörde angemeldet', ['Sie braucht eine Genehmigung vom Bund', 'Sie ist nur am Wochenende erlaubt', 'Sie braucht mindestens 1.000 Teilnehmende'],
 'Versammlungen unter freiem Himmel werden nach den Versammlungsgesetzen vorher angemeldet. Eine Genehmigung brauchen sie nicht.'),
('Gibt es auf Bundesebene Volksentscheide über gewöhnliche Gesetze?',
 'Nein, nur in Ländern und Gemeinden', ['Ja, jedes Jahr im Mai', 'Ja, über jede Steuer', 'Ja, auf Wunsch des Kanzlers und der Regierung'],
 'Das Grundgesetz sieht Volksabstimmungen nur bei einer Neugliederung der Länder vor. Volksbegehren und Bürgerentscheide gibt es in Ländern und Kommunen.'),
('Wer verhandelt für Beschäftigte mit den Arbeitgebern über Tariflöhne?',
 'Gewerkschaften', ['Arbeitgeberverbände', 'Handelskammern', 'Betriebsärzte'],
 'Tarifverträge schließen Gewerkschaften mit Arbeitgebern oder Arbeitgeberverbänden. Der Staat setzt sie nicht fest.'),
('Welche Rolle haben freie Medien in der Demokratie?',
 'Sie informieren die Öffentlichkeit', ['Sie geben Gesetze heraus', 'Sie werden vom Kanzleramt geleitet', 'Sie wählen die Abgeordneten'],
 'Unabhängige Presse und Rundfunk berichten über Politik und decken Missstände auf. Darum schützt sie Artikel 5.'),
('Wer darf für den Bundestag kandidieren?',
 'Deutsche ab 18 Jahren', ['Alle Einwohner ab 16', 'Nur Parteimitglieder', 'Deutsche ab 25 Jahren'],
 'Wählbar ist, wer volljährig und Deutscher ist. Auch Parteilose können als Wahlkreisbewerber antreten.'),
('Muss man in Deutschland zur Wahl gehen?',
 'Nein, es gibt keine Wahlpflicht', ['Ja, sonst droht eine Strafe', 'Ja, ab dem 30. Lebensjahr', 'Nur bei Bundestagswahlen'],
 'Wählen ist ein Recht, keine Pflicht. Wer nicht wählt, wird nicht bestraft.'),
('Was tun Sie mit dem Stimmzettel, nachdem Sie ihn in der Kabine angekreuzt haben?',
 'Gefaltet in die Urne werfen', ['Dem Wahlvorstand offen zeigen', 'Mit nach Hause nehmen', 'Unterschreiben lassen'],
 'Der Stimmzettel wird so gefaltet, dass niemand die Kreuze sieht, und dann in die Wahlurne geworfen. So bleibt die Wahl geheim.'),
('Was ist ein eingetragener Verein (e. V.)?',
 'Zusammenschluss mit Satzung und Vorstand', ['Eine staatliche Behörde', 'Eine Firma mit Aktien', 'Eine politische Partei'],
 'Ein e. V. hat eine Satzung und einen Vorstand und steht im Vereinsregister beim Amtsgericht. Vereine tragen viel ehrenamtliches Engagement.'),
('Wer hilft in vielen Gemeinden ehrenamtlich bei Bränden und Unglücken?',
 'Die Freiwillige Feuerwehr', ['Das städtische Ordnungsamt', 'Der Zoll', 'Die Bundespolizei'],
 'In den meisten Orten löschen Freiwillige Feuerwehren. Ihre Mitglieder sind Ehrenamtliche aus der Gemeinde.'),
('In wie viele Wahlkreise ist Deutschland für die Bundestagswahl eingeteilt?',
 '299', ['250', '316', '598'],
 'Nach dem Bundeswahlgesetz gibt es 299 Wahlkreise. In jedem wird mit der Erststimme ein Bewerber gewählt.'),
('Was bedeutet der Grundsatz der unmittelbaren Wahl?',
 'Wähler bestimmen die Abgeordneten direkt', ['Wahlmänner wählen für das Volk', 'Parteien losen die Sitze aus', 'Der Bundesrat ernennt die Sieger'],
 'Unmittelbar heißt: Zwischen Wählern und Gewählten steht keine weitere Stufe, etwa Wahlmänner.'),
]
